def to_new_statuses(apps, schema_editor):
    """Раньше агент сначала проверял наличие, потом брал оплату. Теперь оплата сразу при заказе."""
    Order = apps.get_model("orders", "Order")
    OrderEvent = apps.get_model("orders", "OrderEvent")
    SupplierOrder = apps.get_model("orders", "SupplierOrder")
    for model in (Order, OrderEvent):
        model.objects.filter(status__in=["new", "confirmed"]).update(status="awaiting_payment")
    unpaid = Order.objects.filter(status__in=["awaiting_payment", "cancelled"]).values("pk")
    SupplierOrder.objects.filter(status="confirm", order__in=unpaid).update(status="pending")
    SupplierOrder.objects.filter(status="confirm").update(status="to_order")
    SupplierOrder.objects.filter(status="ship").update(status="ordered")


